class GithubClientTest {
    @Autowired
    GithubClient client;
    @Autowired
    MockRestServiceServer server;
    @Test
    void fetchesRepoName() {
        server.expect(requestTo("https://api.github.com/repos/spring-projects/spring-boot"))
                .andRespond(withSuccess("spring-boot", MediaType.TEXT_PLAIN));
