import org.springframework.stereotype.Service;

@Service
class ProfileService {

    @PostAuthorize("returnObject.owner == authentication.name")
    Profile find(String id) {
        // 这里没有按用户过滤，靠返回后的校验兜底
        return new Profile(id, "sam");
    }
}

