package com.example.demo.security;

import org.springframework.context.annotation.Configuration;
import org.springframework.security.access.annotation.Secured;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.stereotype.Service;

@Configuration
@EnableMethodSecurity(securedEnabled = true)
class SecuredConfig {
}

@Service
class ReportService {

    // 先开 securedEnabled，@Secured 才会生效
    @Secured("ROLE_ADMIN")
    String secretReport() {
        return "report";
    }
}

package com.example.demo.security;

import jakarta.annotation.security.RolesAllowed;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.stereotype.Service;

@Configuration
@EnableMethodSecurity(jsr250Enabled = true)
class Jsr250Config {
}

@Service
class BillingService {

    // 先开 jsr250Enabled，JSR-250 注解才会生效
    @RolesAllowed({"ADMIN", "BILLING"})
    String invoice() {
        return "invoice";
    }
}

package com.example.demo.web;

import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
class MeController {

    @GetMapping("/me")
    // 直接注入当前登录用户，不用手摸 SecurityContext
    String me(@AuthenticationPrincipal UserDetails user) {
        return user.getUsername();
    }

    @GetMapping("/me/only-name")
    String onlyName(@AuthenticationPrincipal(expression = "username") String username) {
        return username;
    }
}

package com.example.demo.security;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class AdminApiTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    // 伪造管理员身份，受保护接口应放行
    @WithMockUser(username = "admin", roles = "ADMIN")
    void adminCanAccess() throws Exception {
        mockMvc.perform(get("/admin/users"))
                .andExpect(status().isOk());
    }
}
